fn solve(a: i8, b: i8, c: i8) -> i8 {
    // Sort the sides so that x <= y <= z
    let mut sides = [a, b, c];
    sides.sort();

    let x = sides[0];
    let y = sides[1];
    let z = sides[2];

    // We only need to ensure x + y > z.
    // If x + y > z already holds, no operations are needed.
    // Otherwise, we need at least (z - (x + y) + 1) increments
    // distributed to the two smaller sides.
    let deficit = z - x - y + 1;
    if deficit > 0 {
        deficit
    } else {
        0
    }
}

