    #[test]
    fn already_triangle() {
        assert_eq!(solve(3, 4, 5), 0); // 3+4 > 5
        assert_eq!(solve(2, 3, 4), 0); // 2+3 > 4
        assert_eq!(solve(5, 5, 5), 0);
    }

    #[test]
    fn need_operations() {
        // 1+1 <= 3, so need 3 - 2 + 1 = 2 increments
        assert_eq!(solve(1, 1, 3), 2);
        // 2+2 <= 7, so need 7 - 4 + 1 = 4 increments
        assert_eq!(solve(2, 2, 7), 4);
        // 1+2 <= 10, so need 10 - 3 + 1 = 8 increments
        assert_eq!(solve(1, 2, 10), 8);
    }

    #[test]
    fn mixed_order_inputs() {
        // Even if inputs are out of order, sorting handles it.
        assert_eq!(solve(10, 1, 2), 8);
        assert_eq!(solve(7, 2, 2), 4);
        assert_eq!(solve(3, 5, 4), 0);
    }
